+export async function findByUser(userId: string, options: {
+  page: number;
+  limit: number;
+  status?: string;
+}) {
+  const { page, limit, status } = options;
+  const offset = (page - 1) * limit;
+
+  const query = db.orders.where({ userId });
+  if (status) {
+    query.where({ status });
+  }
+
+  const [items, total] = await Promise.all([
+    query.offset(offset).limit(limit).find(),
+    query.count(),
+  ]);
+
+  return {
+    items,
+    pagination: { page, limit, total, pages: Math.ceil(total / limit) },
+  };
+}
